// ============================================================================
// TORAH REGISTRY - Build Registry with Metadata
// ============================================================================

// Torah Workflow Metadata
const torahMetadata = {
  "torah-discord-message": {
    "label": "Discord Commentary Bot",
    "icon": "💬",
    "description": "Recherche de commentaires talmudiques via Discord",
    "tags": ["discord", "talmud", "commentaires"],
    "scope": "user",
    "example": "Sukkah 28b Rashi"
  },
  "torah-translate": {
    "label": "Translation Orchestrator",
    "icon": "🎯",
    "description": "Orchestration du pipeline de traduction Torah",
    "tags": ["traduction", "orchestration"],
    "scope": "system"
  },
  "torah-batch-translate": {
    "label": "Batch Translation",
    "icon": "📚",
    "description": "Traduction en lot avec extraction de commentaires",
    "tags": ["traduction", "batch", "commentaires"],
    "scope": "user"
  },
  "torah-submit-review": {
    "label": "Review Submission",
    "icon": "✅",
    "description": "Soumission de traductions pour révision",
    "tags": ["revision", "validation"],
    "scope": "user"
  },
  "torah-review-action": {
    "label": "Review Action",
    "icon": "📝",
    "description": "Actions de validation (approuver/rejeter/modifier)",
    "tags": ["revision", "validation"],
    "scope": "user"
  },
  "torah-generate-pdf": {
    "label": "PDF Generator",
    "icon": "📄",
    "description": "Génération de PDF avec traductions et commentaires",
    "tags": ["pdf", "export", "document"],
    "scope": "user"
  }
};

const webhook = $env.N8N_BASE_URL;
const webhookBase = $env.N8N_WEBHOOK_BASE_URL;
const apiUrl = $env.API_URL;

//=================================================================
// BUILD REGISTRY
// ============================================================================

const workflows = $input.first().json.data || [];

// Filter active Torah workflows (excluding this registry)
const torahWorkflows = workflows.filter(w => 
  w.active && 
  w.name.startsWith('Torah') && 
  w.name !== 'Torah - Registry'
);

// Build tools object
const tools = {};

for (const workflow of torahWorkflows) {
  // Find all webhook nodes in the workflow
  const webhookNodes = workflow.nodes?.filter(n => n.type === 'n8n-nodes-base.webhook') || [];

  for (const webhookNode of webhookNodes) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;
    const toolName = webhookPath;

    // Get metadata
    const meta = torahMetadata[toolName] || {};

    tools[toolName] = {
      name: workflow.name,
      label: meta.label || workflow.name.replace('Torah ', ''),
      icon: meta.icon || '📜',
      description: meta.description || `Torah Tool: ${workflow.name}`,
      tags: meta.tags || ['torah'],
      scope: meta.scope || 'user',
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `${webhookBase}/${webhookPath}`,
      method: webhookNode.parameters?.httpMethod || 'POST',
      active: workflow.active,
      example: meta.example || null
    };
  }
}

// Build final registry response
const registry = {
  version: "1.0",
  updated_at: new Date().toISOString(),
  n8n: {
    webhook_base: webhookBase
  },
  scopes: {
    user: "Endpoint accessible par l'utilisateur",
    system: "Endpoint interne pour orchestration"
  },
  total_tools: Object.keys(tools).length,
  tools: tools
};

return { json: registry };
